import { useMemo, useState } from 'react';
import { JxBadge, JxPagination, JxTable } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);

  const visible = useMemo(
    () => users.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [users, safePage],
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <JxTable>
        <thead>
          <tr>
            <th>Имя</th>
            <th>Роль</th>
            <th>Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'danger'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
    </div>
  );
}

